"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[86094],{50206:e=>{e.exports=JSON.parse('{"functions":[{"name":"ClampRewind","desc":"Pure. Clamp a client-claimed render time into a safe rewind time.\\nNon-finite / non-positive input means \\"no rewind\\" (returns `now`).","params":[{"name":"now","desc":"","lua_type":"number"},{"name":"renderTime","desc":"","lua_type":"number"},{"name":"ping","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":49,"path":"src/ServerStorage/SharedModules/LagCompensation.luau"}},{"name":"Raycast","desc":"`leviathanTime` (server time, `RockMath.shooterViewTime`) is when the shooter\\nsaw the Leviathan: clients draw it on synced server time, not through the\\nChrono interpolation buffer, so `rewindTo` does not apply to it.","params":[{"name":"origin","desc":"","lua_type":"Vector3"},{"name":"direction","desc":"","lua_type":"Vector3"},{"name":"rewindTo","desc":"","lua_type":"number"},{"name":"exclude","desc":"","lua_type":"{ Instance }"},{"name":"leviathanTime","desc":"","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"Hit?\\n"}],"function_type":"static","source":{"line":94,"path":"src/ServerStorage/SharedModules/LagCompensation.luau"}}],"properties":[],"types":[],"name":"LagCompensation","desc":"Rewinds Chrono-tracked NPCs to the time the shooter saw them. The client\\nsends its Chrono ENEMY render time (server os.clock domain); the server\\nclamps it, reads each NPC\'s snapshot at that time, and shifts the query\\ninto the NPC\'s current pose with `delta = current * past:Inverse()` \u2014 so\\nthe query hits the real current geometry as if the NPC stood where the\\nshooter saw it. Rigid: the animated limb pose is the current one.\\n\\nPlayers are never rewound (Factions allows no PvP). World geometry and\\ndead (paused) NPCs are tested unrewound, as before. The world ray is\\n`WeaponValidation.bulletRaycast`, so invisible non-solid helper parts never block.\\n\\nThe Leviathan (900 studs, too big for the 10-stud broadphase) is tested\\nanalytically at the shot time by [LeviathanBody]; its hitbox parts are\\nleft out of the world ray so the \\"now\\" pose never wins.","realm":["Server"],"source":{"line":21,"path":"src/ServerStorage/SharedModules/LagCompensation.luau"}}')}}]);